package com.vynedam.stockai.service;
import com.vynedam.stockai.dto.InventoryDtos.MaterialRequest; import com.vynedam.stockai.exception.ApiException; import com.vynedam.stockai.model.Material; import com.vynedam.stockai.repository.MaterialRepository; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service;
@Service public class MaterialService { private final MaterialRepository repo; public MaterialService(MaterialRepository r){repo=r;} public List<Material> list(){return repo.findAll();} public Material get(String id){return repo.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"NOT_FOUND","Material not found"));} public Material create(MaterialRequest r){var sku=r.sku().trim().toUpperCase();if(repo.existsBySku(sku))throw new ApiException(HttpStatus.CONFLICT,"DUPLICATE_RECORD","A material with this SKU already exists");var m=new Material();m.sku=sku;apply(m,r);return repo.save(m);} public Material update(String id,MaterialRequest r){var m=get(id);apply(m,r);return repo.save(m);} private void apply(Material m,MaterialRequest r){m.name=r.name().trim();m.category=r.category();m.unit=r.unit();m.reorderPoint=r.reorderPoint()==null?0:r.reorderPoint();m.leadTimeDays=r.leadTimeDays()==null?0:r.leadTimeDays();} }
